export type ParsedRebalanceInstruction<
  TProgram extends string = typeof VAULTS_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    rebalancer: TAccountMetas[0];
    rebalancerSupplyTokenAccount: TAccountMetas[1];
    rebalancerBorrowTokenAccount: TAccountMetas[2];
    /**
     * @dev mut because this PDA signs the CPI to liquidity program
     * @dev verification inside instruction logic
     */
    vaultConfig: TAccountMetas[3];
    /** @dev verification inside instruction logic */
    vaultState: TAccountMetas[4];
    supplyToken: TAccountMetas[5];
    borrowToken: TAccountMetas[6];
    supplyTokenReservesLiquidity: TAccountMetas[7];
    borrowTokenReservesLiquidity: TAccountMetas[8];
    vaultSupplyPositionOnLiquidity: TAccountMetas[9];
    vaultBorrowPositionOnLiquidity: TAccountMetas[10];
    supplyRateModel: TAccountMetas[11];
    borrowRateModel: TAccountMetas[12];
    liquidity: TAccountMetas[13];
    liquidityProgram: TAccountMetas[14];
    vaultSupplyTokenAccount: TAccountMetas[15];
    vaultBorrowTokenAccount: TAccountMetas[16];
    systemProgram: TAccountMetas[17];
    supplyTokenProgram: TAccountMetas[18];
    borrowTokenProgram: TAccountMetas[19];
    associatedTokenProgram?: TAccountMetas[20] | undefined;
  };
  data: RebalanceInstructionData;
};

export function parseRebalanceInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRebalanceInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 21) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 21,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === VAULTS_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      rebalancer: getNextAccount(),
      rebalancerSupplyTokenAccount: getNextAccount(),
      rebalancerBorrowTokenAccount: getNextAccount(),
      vaultConfig: getNextAccount(),
      vaultState: getNextAccount(),
      supplyToken: getNextAccount(),
      borrowToken: getNextAccount(),
      supplyTokenReservesLiquidity: getNextAccount(),
      borrowTokenReservesLiquidity: getNextAccount(),
      vaultSupplyPositionOnLiquidity: getNextAccount(),
      vaultBorrowPositionOnLiquidity: getNextAccount(),
      supplyRateModel: getNextAccount(),
      borrowRateModel: getNextAccount(),
      liquidity: getNextAccount(),
      liquidityProgram: getNextAccount(),
      vaultSupplyTokenAccount: getNextAccount(),
      vaultBorrowTokenAccount: getNextAccount(),
      systemProgram: getNextAccount(),
      supplyTokenProgram: getNextAccount(),
      borrowTokenProgram: getNextAccount(),
      associatedTokenProgram: getNextOptionalAccount(),
    },
    data: getRebalanceInstructionDataDecoder().decode(instruction.data),
  };
}
